def build_report_queries(request: ReportReadParams) -> ReportReadQueries:
    config = _get_config(request.report_name)
    columns = config["columns"]
    projection = ", ".join(
        f"{col.get('select', col['key'])} as {col['key']}" for col in columns
    )
    base_from = config["base_from"]
    where = _filtered_predicate(config)
    _, filter_params = build_filter_conditions(request.filters, columns)
    params = {
        "report_date": request.report_date,
        **filter_params,
        "search_term": f"%{request.search}%" if request.search else None,
        "sort_by": request.sort_by or None,
        "sort_order": "DESC" if str(request.sort_order).upper() == "DESC" else "ASC",
    }
    summary = None
    if config.get("summary"):
        summary = _SUMMARY_QUERY_CACHE.get(request.report_name)
        if summary is None:
            summary = _get_summary_query_clause(request.report_name)
            _SUMMARY_QUERY_CACHE[request.report_name] = summary
    return ReportReadQueries(
        count=_typed_statement(f"SELECT COUNT(*) {base_from} WHERE {where}"),
        total=_typed_statement(f"SELECT COUNT(*) {base_from} WHERE {config['date_condition']}"),
        data=_typed_statement(
            f"SELECT {config.get('id_expr', '1')} as _row_id, {projection} "
            f"{base_from} WHERE {where}{build_sort_clause(columns)} LIMIT :limit OFFSET :offset"
        ),
        summary=summary,
        params=params,
    )


def _decode_value(value: Any) -> Any:
    return float(value) if value is not None and hasattr(value, "__float__") else value


class ReportReadRepository:
    def __init__(self, session: AsyncSession) -> None:
        self._session = session

    @staticmethod
    def report_names() -> list[str]:
        return list(REPORT_REGISTRY)

    async def read(self, request: ReportReadParams) -> ReportReadRows:
        config = _get_config(request.report_name)
        queries = build_report_queries(request)
        filtered_total = (
            await self._session.execute(queries.count, queries.params)
        ).scalar() or 0
        total = (
            await self._session.execute(
                queries.total, {"report_date": request.report_date}
            )
        ).scalar() or 0
        result = await self._session.execute(
            queries.data,
            {**queries.params, "limit": request.limit, "offset": request.offset},
        )
        rows = [
            {
                key: value if key == "_row_id" else _decode_value(value)
                for key, value in row.items()
            }
            for row in result.mappings().all()
        ]
        summary = {}
        if filtered_total > 0 and queries.summary is not None:
            result = await self._session.execute(queries.summary, queries.params)
            summary_row = result.mappings().first()
            if summary_row is not None:
                summary = {
                    item["key"]: {
                        "value": _decode_value(summary_row.get(item["key"])),
                        "label": item["label"],
                        "is_count": item.get("is_count", False),
                    }
                    for item in config["summary"]
                }
        projection = ReportDataConfig(
            table=config["base_from"],
            date_column=config["date_condition"],
            columns=config["columns"],
            summary=config.get("summary", []),
            searchable=config.get("searchable", []),
        )
        return ReportReadRows(
            total, filtered_total, projection.get_columns_meta(), rows, summary
        )

